import { Stack, Chip } from "march/ui"

// etiket bulutu: satır, sarmalı; seçilen etiketler sayılır
const tags = ["sinyal", "TSX", "derleyici", "erişilebilirlik", "tema", "hareket", "test", "i18n"]

export function TagCloud() {
  let $picked: string[] = []
  const toggle = (t: string) => $picked = $picked.includes(t) ? $picked.filter((x) => x !== t) : [...$picked, t]
  return <Stack gap={4}>
    <Stack direction="row" gap={2} wrap>
      {tags.map((t) => <Chip selected={$picked.includes(t)} on:click={() => toggle(t)}>{t}</Chip>)}
    </Stack>
    <span sx={{ text: "sm", color: "muted" }}>{$picked.length} etiket seçildi</span>
  </Stack>
}

import { Stack, Toolbar, Divider, Button } from "march/ui"

// Stack'in bütün özellikleri: direction, gap (0–8), align, justify, wrap, as, class; yanında Toolbar (label, end) ve
// Divider (label, vertical)
const Box = (props: { n: number }) => <span class="sc-stack-item sc-stack-item-0">Öğe {props.n}</span>

export function StackLab() {
  let $gap = 2
  return <Stack gap={4}>
    {() => <Stack class="lab-row" as="ul" direction="row" gap={$gap} align="center" justify="between" wrap>
      {[1, 2, 3].map((n) => <li><Box n={n} /></li>)}
    </Stack>}
    <Toolbar label="Boşluk" end={<span class="lab-gap">gap {$gap}</span>}>
      <Button size="sm" on:click={() => $gap = Math.max(0, $gap - 1)}>Daralt</Button>
      <Divider vertical />
      <Button size="sm" on:click={() => $gap = Math.min(8, $gap + 1)}>Genişlet</Button>
    </Toolbar>
    <Divider label="sütun" />
    <Stack class="lab-col" direction="column" gap={1} align="end"><Box n={4} /><Box n={5} /></Stack>
  </Stack>
}

import { test, expect, renderTest } from "march/testing"
import { StackLab } from "./StackLab.tsx"

// StackLab'in testleri: kaydedince Testler sekmesinde çalışır
test("as=ul listeyi ul olarak çizer, wrap sınıfı var", () => {
  const s = renderTest(() => <StackLab />)
  const row = s.get(".lab-row")!
  expect(row.tagName).toBe("UL")
  expect(row.className).toContain("m-stack-wrap")
})

test("Genişlet boşluğu bir adım artırır", async () => {
  const s = renderTest(() => <StackLab />)
  await s.click("Genişlet")
  expect(s.get(".lab-gap")?.textContent).toBe("gap 3")
  expect(s.get(".lab-row")!.className).toContain("m-gap-3")
})

test("Toolbar erişilebilir adını alır, Divider etiketini gösterir", () => {
  const s = renderTest(() => <StackLab />)
  expect(s.get("[role=toolbar]")?.getAttribute("aria-label")).toBe("Boşluk")
  expect(s.sees("sütun")).toBe(true)
})
